/*
 * Ceremony DEFINITION v6 — the authored artifact the resolver consumes
 * (resolver.js: resolve(definition, eaScores) → linear {layout, beats[]}).
 *
 * CONTENT: transcription of designer-content/End of Game Script v4.md — the
 * FINAL script (received 2026-09-10). Paired with ceremony_v6.html +
 * lib/player_v6.js and the assets/audio_v6/ clip set. The prior
 * ceremony-definition.js (script v3, used by ceremony_v1.html … ceremony_v5.html
 * with assets/audio/) is frozen; do not edit it. Plan: docs/script-v4-plan.md.
 *
 * Script v4 vs v3: dialogue only — 12 lines rewritten to work curriculum
 * concepts in (topography, claims/evidence/reasoning, watersheds, elevation,
 * porosity, evaporation/condensation, argumentation) and ONE behavioural
 * change: u2.dani's U2.C5 threshold ≥ 2 → ≥ 4 (the EA doc's own "On-track:
 * 4–6 pts" band). Stage directions, holo images, highlights, star pop-up:
 * unchanged. The script's "toidentify" (u2.dani.b) is implemented as
 * "to identify".
 *
 * Authoring conventions:
 *  - lineId suffixes .a/.b match the script's Condition A/B labels, which are
 *    standardized: A is always the best-case variant, B the generic one.
 *  - every conditional section puts the HIGH-score predicate in `when` and the
 *    B variant as `otherwise`, so missing scores play the generic line
 *    (designer-confirmed). B variants use the `neutral` expression (also
 *    designer-confirmed — B may be seen by students who never attempted).
 *  - holo.images paths are relative to assets/holo/ — staged JPEG copies of the
 *    script-referenced Screenshots (basenames preserved; .png → .jpg; the Unit 5
 *    "Aryn_s …" underscore filenames stand in for the script's "Aryn's …").
 *  - holo.highlights renders the conclusion's progressive bullet list.
 *  - every text-bearing beat carries a lineId — the key joining it to its voice
 *    clip and word timings in assets/audio_v6/ceremony_audio.json (generated by
 *    mhsaudiotools from tools/ceremony-lines_v6.txt; see tools/export-lines.cjs).
 *    lineIds are unchanged from the v3-script definition, so the 15 untouched
 *    lines keep their approved takes (copied into assets/audio_v6/).
 *  - the conclusion is authored as a `units` entry (speaker Toppo) so the
 *    resolver's fixed order (intro → units → celebration → finale) places the
 *    ending celebration last; `finale` is unused.
 *
 * Still provisional: "Planetary Water Steward" title pending designer sign-off;
 * U2.C3 composition decided provisionally as Tera + Aryn (grader side; this
 * file just sums the two keys). 2026-09-21: u3.garden's bar moved 3 → 2.5 so
 * three correct plots with one wrong planting earn the warmer line, matching
 * the rubric's on-track band (mhsgrading/docs/ea-scores-team-questions-2026-09.md
 * D5). The audio clips did not change.
 */
(typeof window !== 'undefined' ? window : globalThis).CEREMONY_DEFINITION = {
  layout: {
    mc: 'Toppo',
    group: ['Jasper', 'Anderson', 'Aryn', 'Tera'],
  },

  // ================================================================ INTRO / UNIT 1 — TOPPO
  // Script: "Captain Toppo stands at front of stage" → startAtMark (no walk-in).
  intro: [
    {
      lineId: 'u1.intro', speaker: 'Toppo', expression: 'proud', startAtMark: true,
      holo: { images: ['unit1/CopernicusSpaceShipImage.jpg', 'unit1/WAT247.jpg'] },
      // v3 script dropped "Cadet" from the opener (title references removed) —
      // which also retires the old speakText comma workaround. The stability 0.60
      // override in tools/voice-overrides.json stays. If the bare "TK!" opener
      // ever garbles like "Hey, TK-" did, speakText with "TK," is the fix.
      text: "TK! I want to personally congratulate you on everything you've accomplished on WAT247. When we first arrived, our mission was on the verge of being canceled. But you gathered evidence, and convinced Mission Control that water existed on WAT247. Because of your work, the mission continued, and every discovery that followed became possible! Let's take a look back at what your efforts enabled our team to achieve.",
    },
  ],

  units: [
    // ================================================================ UNIT 2 — JASPER
    {
      id: 'unit2', speaker: 'Jasper',
      sections: [
        { id: 'u2.crash',
          always: {
            lineId: 'u2.crash', expression: 'happy',
            text: "TK, after the Copernicus crash-landed, our mission could have ended right there.",
          } },
        // finding the team — sum of U2.C2 (Find Toppo) + U2.C3 (Find Tera), ≥2 of 2.5
        { id: 'u2.find-team',
          conditions: [
            { when: { sum: ['U2.C2', 'U2.C3'], op: '>=', value: 2 },
              beat: {
                lineId: 'u2.find-team.a', expression: 'happy',
                text: "but you demonstrated your knowledge of topography and used the map to find our missing team members quickly and helped us get the mission back on track.",
                holo: { images: ['unit2/Find Toppo.jpg', 'unit2/Find Tera.jpg', 'unit2/Find Aryn.jpg', 'unit2/Find Team.jpg'] },
              } },
            { otherwise: true,
              beat: {
                lineId: 'u2.find-team.b', expression: 'neutral',
                text: "but you found the missing team members and helped us get the mission back on track.",
                holo: { images: ['unit2/Find Toppo.jpg', 'unit2/Find Tera.jpg', 'unit2/Find Aryn.jpg', 'unit2/Find Team.jpg'] },
              } },
          ] },
        // DANI's argumentation system — U2.C5 (raw points, ≈6 max). Script v4 raised
        // the happy-line bar from 2 to 4 = the EA doc's "On-track: 4–6 pts" band.
        { id: 'u2.dani',
          conditions: [
            { when: { item: 'U2.C5', op: '>=', value: 4 },
              beat: {
                lineId: 'u2.dani.a', expression: 'happy',
                text: "After DANI's argumentation system was broken, you were able to successfully identify claims, evidence and reasoning in arguments and got him back online in no time.",
                holo: { images: ['unit2/Classifier.jpg', 'unit2/classifier_DANI.jpg'] },
              } },
            { otherwise: true,
              beat: {
                lineId: 'u2.dani.b', expression: 'neutral',
                // script reads "toidentify" — a missing space, implemented as "to identify"
                text: "When DANI's argumentation system was broken, you worked hard to identify claims, evidence and reasoning.",
                holo: { images: ['unit2/Classifier.jpg', 'unit2/classifier_DANI.jpg'] },
              } },
          ] },
        // choosing the water source / base location — U2.C7
        { id: 'u2.water',
          conditions: [
            { when: { item: 'U2.C7', op: '>=', value: 2 },
              beat: {
                lineId: 'u2.water.a', expression: 'happy',
                text: "One of your biggest decisions was evaluating the available watersheds and topography to select the best location for our new base. That decision gave our team reliable access to the water we needed to survive!",
                holo: { images: ['unit2/Collect Evidence.jpg'] },
              } },
            { otherwise: true,
              beat: {
                lineId: 'u2.water.b', expression: 'neutral',
                text: "One of your biggest decisions was evaluating the available watersheds. Even though it took a few tries you eventually selected the best location for our new base. That decision gave our team reliable access to the water we needed to survive.",
                holo: { images: ['unit2/Collect Evidence.jpg'] },
              } },
          ] },
        { id: 'u2.thanks',
          always: {
            lineId: 'u2.thanks', expression: 'happy',
            text: "Thank you for everything you did, TK. Tera's been waiting to thank you too.",
          } },
      ],
    },

    // ================================================================ UNIT 3 — TERA
    {
      id: 'unit3', speaker: 'Tera',
      sections: [
        // crate placements — U3.C1; the two variants show DIFFERENT images
        { id: 'u3.crates',
          conditions: [
            { when: { item: 'U3.C1', op: '>=', value: 2 },
              beat: {
                lineId: 'u3.crates.a', expression: 'happy',
                text: "When I needed help getting my lost equipment crates back to my base, you used what you knew about surface water flowing from upper to lower elevations and topography to safely float them down the river.",
                holo: { images: ['unit3/U3 Crate Task Correct 2.jpg', 'unit3/U3 Crate Task.jpg'] },
              } },
            { otherwise: true,
              beat: {
                lineId: 'u3.crates.b', expression: 'neutral',
                text: "When I needed help getting my lost equipment crates back to my base, you did your best to help float them from higher to lower elevations down the river. Even though some misunderstandings about surface water flow meant we couldn't recover every crate, I appreciated your willingness to help.",
                holo: { images: ['unit3/U3 Crate Task Incorrect.jpg', 'unit3/U3 Crate Task Incorrect 2.jpg'] },
              } },
          ] },
        { id: 'u3.pollution',
          always: {
            lineId: 'u3.pollution', expression: 'happy',
            text: "And when our water supply was in danger, you helped me track down the ship battery that was contaminating our waterways. Once it was removed, we finally had access to clean water.",
            holo: { images: ['unit3/U3 Pollution Task.jpg', 'unit3/U3 Pollution Task 2.jpg', 'unit3/U3 Pollution Task 3.jpg'] },
          } },
        // superfruit garden plots — U3.C5 (designer-confirmed; the v1 script's "C4" was a typo)
        { id: 'u3.garden',
          conditions: [
            { when: { item: 'U3.C5', op: '>=', value: 2.5 },   // 2026-09-21: was 3; "3 correct plots" = 3 − ½ for the wrong one (mhsgrading/docs/ea-scores-team-questions-2026-09.md D5)
              beat: {
                lineId: 'u3.garden.a', expression: 'happy',
                text: "Later, when our food supply was running low, you figured out the best places to plant superfruit using what you knew about how dissolved materials move through watersheds. Your decisions allowed the plants to thrive and produce enough food to support the mission!",
                holo: { images: ['unit3/U3 Garden Task Correct Updated.jpg', 'unit3/U3 Garden Task Correct 2.jpg'] },
              } },
            { otherwise: true,
              beat: {
                lineId: 'u3.garden.b', expression: 'neutral',
                text: "Later, when our food supply was running low, you worked to help us identify the best places to plant superfruit downstream from the super nutrient. Although some of your garden plot choices didn't work out as planned, your efforts helped us learn more about how nutrients move through the watershed.",
                holo: { images: ['unit3/U3 Garden Task Incorrect Updated.jpg', 'unit3/U3 Garden Task Incorrect 2.jpg'] },
              } },
          ] },
        { id: 'u3.thanks',
          always: {
            lineId: 'u3.thanks', expression: 'happy',
            text: "We couldn't have done it without you. Thank you, TK!",
          } },
      ],
    },

    // ================================================================ UNIT 4 — ANDERSON
    {
      id: 'unit4', speaker: 'Anderson',
      sections: [
        { id: 'u4.well',
          always: {
            lineId: 'u4.well', expression: 'happy',
            text: "TK, you applied your knowledge of groundwater to determine the best location to drill our well. This allowed the team to activate the fountain and restore water to the area.",
            holo: { images: ['unit4/drill well.jpg', 'unit4/drill floors.jpg', 'unit4/dungeon.jpg'] },
          } },
        { id: 'u4.flood',
          always: {
            lineId: 'u4.flood', expression: 'happy',
            text: "And when my underground bunker began flooding, you analyzed the porosity of the ground at the different floors and convinced me that it wouldn't stop on its own. Your quick thinking saved my life! I can't thank you enough for helping me get out alive!",
            holo: { images: ['unit4/arg scan.jpg', 'unit4/save anderson.jpg'] },
          } },
        // seedling soil choice via camera placements — U4.C6
        { id: 'u4.soil',
          conditions: [
            { when: { item: 'U4.C6', op: '>=', value: 2 },
              beat: {
                lineId: 'u4.soil.a', expression: 'happy',
                text: "You even used your understanding of soil infiltration to help identify the best soil type to use with our seedlings. Because of you, we have more fresh food to go around!",
                holo: { images: ['unit4/garden boxes.jpg'] },
              } },
            { otherwise: true,
              beat: {
                lineId: 'u4.soil.b', expression: 'neutral',
                text: "You even worked with me to help identify the best soil type to use with our seedlings.",
                holo: { images: ['unit4/garden boxes.jpg', 'unit4/garden boxes 2.jpg', 'unit4/garden boxes 3.jpg'] },
              } },
          ] },
        { id: 'u4.thanks',
          always: {
            lineId: 'u4.thanks', expression: 'happy',
            text: "Your hard work is appreciated, TK!",
          } },
      ],
    },

    // ================================================================ UNIT 5 — ARYN
    {
      id: 'unit5', speaker: 'Aryn',
      sections: [
        // Sea WAT-er plant evaporation argument — U5.C3 (>0 = earned any points)
        { id: 'u5.plant',
          conditions: [
            { when: { item: 'U5.C3', op: '>', value: 0 },
              beat: {
                lineId: 'u5.plant.a', expression: 'happy',
                // spoken "TK," — the script's "TK-" glues the dash into the next word
                // and garbles the "Tea Kay" pronunciation; display keeps "TK-"
                speakText: "Hey, TK, I was so convinced that aliens had stolen water from my Sea WAT-er plant, but you used your excellent knowledge of evaporation and condensation to convince me that the water evaporated due to natural causes.",
                text: "Hey, TK- I was so convinced that aliens had stolen water from my Sea WAT-er plant, but you used your excellent knowledge of evaporation and condensation to convince me that the water evaporated due to natural causes.",
                holo: { images: ['unit5/Aryn_s plant outside.jpg', 'unit5/Aryn_s plant.jpg', 'unit5/Inside Aryn plant.jpg'] },
              } },
            { otherwise: true,
              beat: {
                lineId: 'u5.plant.b', expression: 'neutral',
                speakText: "Hey, TK, I was so convinced that aliens had stolen water from my Sea WAT-er plant, but you convinced me that the water evaporated due to natural causes.",
                text: "Hey, TK- I was so convinced that aliens had stolen water from my Sea WAT-er plant, but you convinced me that the water evaporated due to natural causes.",
                holo: { images: ['unit5/Aryn_s plant outside.jpg', 'unit5/Aryn_s plant.jpg', 'unit5/Inside Aryn plant.jpg'] },
              } },
          ] },
        // solar still — U5.C4 (designer-confirmed; v2 script's "C5" was a typo).
        // One-chance EA scoring: three ½-point selections, max 1.5; any correct
        // selection (> 0) earns the A variant.
        { id: 'u5.still',
          conditions: [
            { when: { item: 'U5.C4', op: '>', value: 0 },
              beat: {
                lineId: 'u5.still.a', expression: 'happy',
                text: "It was also because of your incredible work that we were able to properly set up the solar still to use your knowledge of evaporation and condensation to convert sea water into drinkable water. Now we'll have the fresh water we need!",
                holo: { images: ['unit5/Solar still after.jpg'] },
              } },
            { otherwise: true,
              beat: {
                lineId: 'u5.still.b', expression: 'neutral',
                text: "You also did your best to help set up the solar still to use your knowledge of evaporation and condensation to convert sea water into drinkable water. Though it's not perfect yet, I know your work will help us get closer to having enough fresh water for everyone.",
                holo: { images: ['unit5/Solar still before.jpg'] },
              } },
          ] },
        { id: 'u5.handoff',
          always: {
            lineId: 'u5.handoff', expression: 'happy',
            text: "I think Captain Toppo has one final thing to show you.",
          } },
      ],
    },

    // ================================================================ CONCLUSION — TOPPO
    {
      id: 'conclusion', speaker: 'Toppo',
      sections: [
        // the five highlights materialize one at a time across this line and hold
        { id: 'end.skills',
          always: {
            lineId: 'end.skills', expression: 'proud',
            holo: { highlights: [
              'Investigated evidence',
              'Analyzed data',
              'Solved environmental problems',
              'Protected water resources',
              'Supported life on WAT247',
            ] },
            text: "TK, throughout this mission, you've demonstrated the skills of a scientist, an engineer, and a problem solver. Those skills changed the course of this mission.",
          } },
        // no holo → the highlights stay up during the award line.
        { id: 'end.award',
          always: {
            lineId: 'end.award', expression: 'proud',
            text: "Most importantly, you've shown how your understanding of water systems allowed you to make good arguments that helped us all make better decisions that ultimately affected people, ecosystems, and our entire community. On behalf of the Mission HydroSci expedition, it is my honor to recognize your contributions. I hereby award you the Planetary Water Steward award!",
          } },
      ],
    },
  ],

  // ================================================================ ENDING
  // v3 script: "Toppo presents players with a trophy. NPCs clap and cheer." →
  // star pop-up ("Congratulations! You completed the mission." + per-unit stars)
  // → fade to black. The resolver attaches `stars` from the EA scores to this
  // beat; `ending: 'fade'` runs the celebrate → stars → fade sequence.
  celebration: {
    gesture: 'cheer', expression: 'happy', fx: 'confetti',
    holo: { title: 'PLANETARY WATER STEWARD', subtitle: 'Awarded to TK — Mission HydroSci' },
    advance: 'auto', duration: 6, ending: 'fade',
  },

  finale: [],
};
